import { model, Schema } from "mongoose";
import {
  BreedCategories,
  BreedPurposes,
  ResistanceLevels,
  Temperaments,
} from "./breed.constants.js";
import type { TBreed } from "./breed.interface.js";

const breedSchema = new Schema<TBreed>(
  {
    //generated by generateBreedCode (BREED-00001) and never accepted from the client
    breedCode: {
      type: String,
      required: true,
      unique: true,
      immutable: true,
      trim: true,
      uppercase: true,
    },
    breedName: { type: String, required: true, trim: true, maxlength: 100 },
    origin: { type: String, required: true, trim: true, maxlength: 100 },
    category: {
      type: String,
      enum: Object.values(BreedCategories),
      required: true,
    },
    purpose: {
      type: String,
      enum: Object.values(BreedPurposes),
      required: true,
    },
    //breed-level reference values, not measurements of any individual animal
    averageMilkPerDay: { type: Number, min: 0 },
    averageAdultWeight: { type: Number, min: 0.01 },
    averageDailyFeed: { type: Number, min: 0 },
    heatTolerance: { type: String, enum: Object.values(ResistanceLevels) },
    temperament: { type: String, enum: Object.values(Temperaments) },
    colorPattern: { type: String, trim: true, maxlength: 100 },
    image: { type: String, trim: true },
    diseaseResistance: { type: String, enum: Object.values(ResistanceLevels) },
    isNative: { type: Boolean, required: true, default: false },
    description: { type: String, trim: true, maxlength: 2000 },
    //breeds are deactivated, never hard-deleted, so existing Animal references stay valid
    isActive: { type: Boolean, required: true, default: true },
  },
  { timestamps: true },
);

//case-insensitive uniqueness so "Holstein Friesian" / "Holstein friesen" cannot both exist
breedSchema.index(
  { breedName: 1 },
  { unique: true, collation: { locale: "en", strength: 2 } },
);

//list/filter endpoint: active breeds by category and purpose
breedSchema.index({ isActive: 1, category: 1, purpose: 1 });

export const BreedModel = model<TBreed>("Breed", breedSchema);
